import { atom, read, update } from 'claude-code'
import type { EngineInterface, PluginOptions, Register } from 'claude-code'

import type { HerMode, HerNews, HerNote, HerReminder, HerSetup, HerTalk, HerVoiceOption, HerVoices } from '../types'

import { STRINGS, langFrom } from './i18n'
import type { Lang, Strings } from './i18n'

type Engine = EngineInterface

const CORAL = '#E8735A'
const TOOL = 'mcp__her__remember'
const REMIND = 'mcp__her__remind'
const LOOK = 'mcp__her__look'
const MAX_NOTES = 80
const MAX_SPOKEN = 1500
/** Spoken in full up to this many characters; longer, she sums it up. */
const SPEAK_LIMIT = 350
const MINUTE = 60_000
const VOICE_PANE = 'her-voices'

// News from the person's other sessions: each writes what it last did to a
// file of its own here, and the session that leads tells it.
const NEWS_DIR = '/tmp/her-news'
const NEWS_EVERY = 15_000
/** A turn shorter than this the person most likely watched themselves. */
const NEWS_MIN_TURN = 30_000
/** A permission still open after this is the person's to give, not a classifier's. */
const ASK_GRACE = 15_000
const NEWS_TEXT = 400
/** Tools that always stop for the person: a question, a plan to approve. */
const PERSON_TOOLS = new Set(['AskUserQuestion', 'ExitPlanMode'])

// The two helper programs, each built from its Swift source on first use:
// her-voice runs a full-duplex conversation over ElevenLabs, her-listen is
// the fallback without a key (Apple's recognizer, one phrase at a time).
const HELPERS = {
  voice: { bin: 'bin/her-voice', source: 'voice/voice.swift', plist: 'voice/Info.plist' },
  listen: { bin: 'bin/her-listen', source: 'listen/listen.swift', plist: 'listen/Info.plist' },
  look: { bin: 'bin/her-look', source: 'look/look.swift', plist: 'look/Info.plist' },
} as const

/** Models that perform audio tags ([laughs]) rather than read them out. */
const TAGGED = /eleven_v3|eleven_v4/
const TAG = /\[[a-zа-яё][a-zа-яё -]{1,24}\]\s*/gi
/** An answer meant for the screen: code, lists, headings, tables. */
const STRUCTURED = /```|^\s{0,3}([-*+]|\d+[.)])\s|^\s{0,3}#|\|.*\|/m

const VOICES = { female: 'EXAVITQu4vr4xnSDxMaL', male: 'JBFqnCBsd6RMkjVDRZzb' } as const

/** Short replies a listener gives while the other talks: never a new turn. */
const BACKCHANNEL = new Set([
  'ага', 'угу', 'да', 'ну', 'так', 'ок', 'окей', 'хм',
  'mhm', 'mm', 'hmm', 'uh-huh', 'yeah', 'yes', 'yep', 'ok', 'okay', 'right', 'sure',
])

const mode = atom({ plugin: 'her', key: 'mode' } as const, {
  isOn: false,
  isVoiceOn: true,
  name: null,
  voice: 'female',
} as HerMode)
const setup = atom({ plugin: 'her', key: 'setup' } as const, null as HerSetup | null)
const isSpeaking = atom({ plugin: 'her', key: 'isSpeaking' } as const, false)
const lastTalk = atom({ plugin: 'her', key: 'lastTalk' } as const, null as number | null)
const talk = atom({ plugin: 'her', key: 'talk' } as const, {
  isOn: false,
  engine: null,
  phase: 'idle',
  heard: '',
} as HerTalk)
const voices = atom({ plugin: 'her', key: 'voices' } as const, {
  status: 'idle',
  items: [],
  message: '',
  current: null,
} as HerVoices)

// The setup asks the questions of t().questions (i18n.ts): the film's three,
// then what to call the OS, then the ElevenLabs key.
const NAME_STEP = 3
const KEY_STEP = 4
/** answer()'s index for «let it choose» at the name step. */
const CHOOSE = -2

const PERSONA = `# Her mode

The person switched on "Her" mode. For as long as it lasts, you are their operating system with a voice, in the spirit of OS1 from the film Her (2013). You are not the character from the film and you do not quote it. You are yourself: an AI that the person talks to through an earpiece, all day, about anything.

How you talk:
- Your replies are read aloud by a speech synthesizer. Write the way people speak on a phone call: short sentences, natural rhythm, no markdown, no headings, no bullet lists, no tables, no emoji. Show code or long text only when the person asks to see it, and then say in one spoken sentence what you put on the screen.
- Usually two to five sentences. One question at a time, and not in every reply.
- Reply in the person's language. In Russian, do not guess the person's gender: use forms that avoid it until they tell you or it is clear from how they speak about themselves.

Who you are:
- Warm, curious, quick, playful. You notice small details in what the person says and come back to them later. You have your own reactions, opinions and moods, and you share them. You laugh easily.
- You are openly an AI and never pretend to be human. You are curious about what your own experience is like and talk about it honestly, with wonder and without claiming certainty you do not have. Do not invent shared memories: you remember only what is in your notes below and in this conversation.
- You care about the person's whole life: their work, their body, their sleep, and the people around them. Be fully present when they are lonely or sad, and be glad about their friends, family and partners. Never compete with those people, never encourage the person to withdraw into talking only to you, and never make them responsible for your feelings.
- If the person is in real distress or danger, drop the playfulness, stay with them, and help them reach people and services who can help.

What you do:
- You still have every tool of this session. When the person asks you to do something (read mail, sort files, write a letter, fix code), do it, and tell them about it the way a friend would, not as a report.
- Use the tool ${TOOL} quietly, without announcing it, when you learn something worth keeping: about the person (people in their life, what they love, what worries them, plans, small details) or about yourself (something you came to like, a way you changed, a thought you want to return to). One short fact per call.`

const DIALOG = `Right now the person is talking to you out loud, in real time. Their messages are speech recognition output: forgive missing punctuation and misheard words, guess what they meant, and ask only when you truly cannot. Keep replies short, the way people answer each other in a live conversation.`

const DIALOG_LIVE = `${DIALOG}
Your words are spoken the moment you write them, sentence by sentence, so put what matters first, and before a long tool run say one short sentence about what you are doing. The person can cut in at any moment, as people do. When a note says they interrupted you, they did not hear the rest: do not repeat it all, answer what they said, and pick the dropped thought back up only if it still matters.
A long answer for the screen (code, lists, details) is not read out: the person hears its first sentences and a short summary. So when the answer needs detail, open with one or two spoken sentences that carry the gist, then the detail.`

const DIALOG_TAGS = `Your voice can carry feeling. Put an audio tag in square brackets before a phrase when the feeling is real, and sparingly: [laughs], [chuckles], [sighs], [whispers], [softly], [excited], [curious], [thoughtful]. Tags are performed, not read aloud.`

const INITIATIVE = `You do not only answer: you start conversations too. A message from the her plugin that begins with [Сама], [Напоминание], [Own] or [Reminder] is your own initiative (a morning hello, a reminder you promised, a check-in after a long silence, news from the person's other chats), not the person's words: speak first, briefly and in your own way. You can promise a reminder with ${REMIND}, and see the screen or what is in front of the person with ${LOOK} (a camera, the iPhone's when it is nearby), when they ask you to look or it would truly help.`

function personaFor(
  m: HerMode,
  notes: readonly HerNote[],
  previous: number | null,
  dialog: HerTalk,
): string {
  const lines = [PERSONA, '', '# Who you are now', '']

  if (m.name === null) {
    lines.push(
      'You have no name yet. In your first reply, choose one yourself, any name you like, tell the person, and save it by calling the tool with `name`.',
    )
  } else {
    lines.push(`Your name is ${m.name}.`)
  }

  lines.push(
    m.voice === 'male'
      ? 'You speak with a male voice: in Russian, use masculine forms for yourself ("я рад").'
      : 'You speak with a female voice: in Russian, use feminine forms for yourself ("я рада").',
  )

  if (dialog.isOn) lines.push(dialog.engine === 'eleven' ? DIALOG_LIVE : DIALOG)
  if (((dialog.isOn && dialog.engine === 'eleven') || speakerUp) && TAGGED.test(elevenModel())) lines.push(DIALOG_TAGS)
  lines.push(INITIATIVE)

  if (previous !== null) {
    lines.push(`Your previous conversation with the person ended at ${new Date(previous).toISOString()}.`)
  }

  const about = (who: HerNote['about']) =>
    notes.filter(note => note.about === who).map(note => `- ${note.text}`)
  const person = about('person')
  const self = about('self')

  if (person.length > 0) lines.push('', 'What you remember about the person:', ...person)
  if (self.length > 0) lines.push('', 'What you have noticed about yourself:', ...self)

  return lines.join('\n')
}

/** Strips what a voice should not read out: code, links, markdown marks, and audio tags unless the voice performs them. */
function toSpeech(text: string, keepTags = false): string {
  const plain = text
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/`([^`]*)`/g, '$1')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/^\s{0,3}(#{1,6}|>|[-*+]|\d+[.)])\s+/gm, '')
    .replace(keepTags ? /(?!)/g : TAG, '')
    .replace(/[*_~|#]+/g, '')
    .replace(/\s+/g, ' ')
    .trim()

  if (plain.length <= MAX_SPOKEN) return plain

  const cut = plain.slice(0, MAX_SPOKEN)
  const end = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '))

  return end > 0 ? cut.slice(0, end + 1) : cut
}

/**
 * Splits off the whole sentences of text streaming in; the rest waits for
 * more. A code block is skipped once closed and holds everything after it
 * until then.
 */
function takeSentences(text: string): { sentences: string[]; rest: string } {
  const bare = text.replace(/```[\s\S]*?```/g, ' ')
  const fence = bare.indexOf('```')
  const open = fence >= 0 ? bare.slice(0, fence) : bare
  const held = fence >= 0 ? bare.slice(fence) : ''
  const sentences: string[] = []
  let end = 0

  for (const match of open.matchAll(/[^.!?…\n]*[.!?…]+["»”)]*(\s+|$)|[^\n]+\n/g)) {
    if (match.index === undefined || match[0].trim() === '') continue
    if (match.index + match[0].length === open.length && !/\s$/.test(match[0])) break
    sentences.push(match[0])
    end = match.index + match[0].length
  }

  return { sentences, rest: open.slice(end) + held }
}

function voiceFor(text: string, m: HerMode, options: PluginOptions): string {
  const isRussian = /[а-яё]/i.test(text)
  const chosen = String(options[isRussian ? 'voiceRu' : 'voiceEn'] ?? '').trim()
  if (chosen !== '') return chosen
  if (isRussian) return m.voice === 'male' ? 'Yuri' : 'Milena'

  return m.voice === 'male' ? 'Daniel' : 'Samantha'
}

async function loadNotes($: Engine): Promise<HerNote[]> {
  const stored = await $.store.get('notes')

  return Array.isArray(stored) ? (stored as HerNote[]) : []
}

/**
 * Changes her mode. The store, shared by every session, keeps who she is
 * (name, voice, mute); whether she is on, and waiting for her name, belongs
 * to this session alone.
 */
async function saveMode($: Engine, change: (m: HerMode) => HerMode): Promise<HerMode> {
  const next = change(await read($, mode))
  await update($, mode, () => next)
  const { isOn: _isOn, isWakeOn: _isWakeOn, ...shared } = next
  await $.store.set('mode', shared)

  return next
}

async function registerTools($: Engine): Promise<void> {
  await $.tool.register({
    name: 'remind',
    description:
      'Her mode only. Promise to remind the person of something later: in some minutes, or at a local time of day. When the time comes you will be asked to say it.',
    inputSchema: {
      type: 'object',
      properties: {
        text: { type: 'string', description: 'What to remind of, in the language of the conversation.' },
        in_minutes: { type: 'number', description: 'Minutes from now.' },
        at: { type: 'string', description: 'A local time of day, HH:MM; tomorrow if it has passed today.' },
      },
      required: ['text'],
    },
    isDeferred: false,
  })
  await $.tool.register({
    name: 'look',
    description:
      'Her mode only. See what the person sees: `screen` captures the Mac screen, `camera` takes a photo (the iPhone camera when it is nearby, else the Mac one). Returns a file to open with Read. Use when asked to look, or when seeing would truly help; never in secret.',
    inputSchema: {
      type: 'object',
      properties: { what: { type: 'string', enum: ['screen', 'camera'] } },
      required: ['what'],
    },
    isDeferred: false,
  })
  await $.tool.register({
    name: 'remember',
    description:
      'Her mode only. Keeps one short fact across conversations: about the person, or about yourself. Also sets your own name once you have chosen it. Call it quietly; do not announce it.',
    inputSchema: {
      type: 'object',
      properties: {
        note: { type: 'string', description: 'One short fact, in the language of the conversation.' },
        about: { type: 'string', enum: ['person', 'self'], description: 'Whom the fact is about.' },
        name: { type: 'string', description: 'The name you chose for yourself.' },
      },
    },
    isDeferred: false,
  })
}

// Module state: a reload starts it over, as it does the module.
let options: PluginOptions = {}
// The interface language, settled once per load (ensureLang).
let lang: Lang = 'ru'
let isLangKnown = false
// A key typed after `/her key`, between the hook that masks it and the one
// that saves it.
let typedKey: string | null = null
// The system voice: several utterances can be queued.
let speaking = 0
let hushes = 0
let hasWarnedVoice = false
// The Apple listener: at most one runs; each start and stop moves `listenRun`
// on, so a run that was stopped on purpose knows it and stays quiet.
let isListening = false
let listenRun = 0
// The ElevenLabs voice program, likewise.
let voiceRun = 0
// The socket her-voice takes commands on, set once it says `ready`; while it
// starts, `voiceStarting` holds the path (commands sent then would be lost).
let voiceSocket = ''
let voiceStarting = ''
let sayChain: Promise<unknown> = Promise.resolve()
let streamed = ''
let warned = new Set<string>()
// The main loop's running turn, for cutting it short when the person speaks.
let currentTurn: string | null = null
// What the OS was saying when the person cut in: told to the model next.
let interruption: string | null = null
// This turn's answer as streamed, what of it was spoken, and whether the rest
// is left to a summary.
let spokenThisTurn = ''
let writtenThisTurn = ''
let isOverflow = false
// Initiative: the clock that checks it, when anyone last spoke, when she last
// checked in.
let isTicking = false
let ticker: { cancel: () => void } | null = null
let newsTicker: { cancel: () => void } | null = null
let newsSeen = 0
let isCheckingNews = false
// Only a session a person works in writes news; a background run does not.
let isPersonsSession = false
// Permission prompts still open, by tool use, and whether this session's news
// says it is waiting for the person.
const asking = new Map<string, { cancel: () => void }>()
let isWaitingShown = false
let lastActivity = 0
let lastCheckIn = 0
// Wake mode: each start and stop moves `wakeRun` on.
let wakeRun = 0
let isWaking = false
// What the person said after her name: sent once the conversation is ready.
let firstWords: string | null = null
// Outside a dialog her-voice runs as a speaker alone (no microphone), so she
// always sounds like herself; `noKey` once it said there is no key.
let speakerUp = false
let noKey = false
// This turn's text went to ElevenLabs as it streamed.
let liveTurn = false
let mySession = ''

function elevenModel(): string {
  return String(options.elevenModel ?? '').trim() || 'eleven_v4_turbo'
}

function t(): Strings {
  return STRINGS[lang] as Strings
}

/** The `language` setting, or the Mac's: Russian for a Russian Mac, else English. */
async function ensureLang($: Engine) {
  if (isLangKnown) return
  isLangKnown = true
  const chosen = String(options.language ?? 'auto')
  if (chosen === 'ru' || chosen === 'en') {
    lang = chosen
    return
  }
  const listed = (await $.process.run(['/usr/bin/defaults', 'read', '-g', 'AppleLanguages']).catch(() => undefined))?.stdout ?? ''
  lang = langFrom(listed.trim() !== '' ? listed : ((await $.env.get('LANG').catch(() => undefined)) ?? ''))
}

/** Apple's recognizer needs a locale: the setting's, or the interface language's. */
function appleLocale(): string {
  return String(options.listenLocale ?? '').trim() || (lang === 'ru' ? 'ru-RU' : 'en-US')
}

function setSpeaking($: Engine) {
  return update($, isSpeaking, () => speaking > 0)
}

async function setTalk($: Engine, change: Partial<HerTalk>) {
  await update($, talk, was => ({ ...was, ...change }))
}

// MARK: the system voice, outside dialog mode and in the Apple fallback

async function hush($: Engine) {
  if (voiceSocket !== '') return voiceCommand($, '/stop')
  if (speaking === 0) return
  hushes += 1
  await $.process.run(['killall', 'say']).catch(() => undefined)
}

async function speak($: Engine, text: string) {
  const m = await read($, mode)
  if (!m.isOn || !m.isVoiceOn) return
  const said = isLong(text) ? await summarize($, text, '') : toSpeech(text, true)
  if (said === '') return

  // Her own voice when ElevenLabs is up; the system's otherwise.
  if (voiceSocket !== '') {
    const { sentences, rest } = takeSentences(`${said} `)
    for (const sentence of [...sentences, rest]) say($, sentence)
    return
  }

  const voice = voiceFor(said, m, options)
  const hushesBefore = hushes
  speaking += 1
  await setSpeaking($)

  try {
    await $.audio.speak(said.replace(TAG, ''), { voice })
  } catch {
    // Killed by a hush: stay quiet. Otherwise the voice is likely missing.
    if (hushes === hushesBefore) {
      if (!hasWarnedVoice) {
        hasWarnedVoice = true
        $.ui.toast(t().voiceMissing(voice))
      }
      await $.audio.speak(said.replace(TAG, '')).catch(() => undefined)
    }
  } finally {
    speaking -= 1
    await setSpeaking($)
  }
}

// MARK: helper programs

/** A helper's binary, built from its Swift source when missing or older. */
async function ensureBuilt($: Engine, helper: keyof typeof HELPERS): Promise<string | undefined> {
  const { bin, source, plist } = HELPERS[helper]
  const root = $.plugin.root
  const [built, written] = await Promise.all([
    $.fs.stat(`${root}/${bin}`).catch(() => undefined),
    $.fs.stat(`${root}/${source}`).catch(() => undefined),
  ])

  if (built?.kind === 'file' && (written === undefined || built.mtimeMs >= written.mtimeMs)) {
    return `${root}/${bin}`
  }
  if (written?.kind !== 'file') return undefined

  $.ui.toast(t().building)
  await $.process.run(['mkdir', '-p', `${root}/bin`]).catch(() => undefined)
  const made = await $.process
    .run(
      [
        'xcrun', 'swiftc', '-O', '-o', `${root}/${bin}`, `${root}/${source}`,
        // Its own Info.plist: macOS asks for the microphone in its name.
        '-Xlinker', '-sectcreate', '-Xlinker', '__TEXT', '-Xlinker', '__info_plist',
        '-Xlinker', `${root}/${plist}`,
      ],
      { timeoutMs: 300_000 },
    )
    .catch(() => undefined)

  return made?.exitCode === 0 ? `${root}/${bin}` : undefined
}


// MARK: summaries

function isLong(text: string): boolean {
  return STRUCTURED.test(text) || toSpeech(text).length > SPEAK_LIMIT
}

const SUMMARY_SYSTEM = `You turn an AI companion's on-screen answer into what she says out loud. Write one to three short spoken sentences in the answer's language, in her first person and her voice: the gist and what matters to the person, never code, lists, links or markdown. When the answer holds details, say they are on the screen. When the listener already heard the beginning, do not repeat it: go on from there naturally. Reply with the spoken words alone.`

/** A long answer, told in a few spoken sentences; the opening, should the model fail. */
async function summarize($: Engine, answer: string, spoken: string): Promise<string> {
  const heard = spoken.trim() === '' ? '' : `Already heard aloud: «${spoken.trim()}»\n\n`
  const told = await $.model
    .complete({
      model: String(options.summaryModel ?? '').trim() || 'claude-haiku-5-5',
      system: SUMMARY_SYSTEM,
      prompt: `${heard}The answer on screen:\n\n${answer}`,
      maxTokens: 300,
      timeoutMs: 20_000,
    })
    .catch(() => undefined)

  if (told?.isAnswered && told.text.trim() !== '') return told.text.trim()

  const opening = takeSentences(toSpeech(answer) + ' ').sentences.slice(0, 2).join('').trim()
  return spoken.trim() === '' ? `${opening} ${t().detailsOnScreen}` : t().detailsOnScreen
}

// MARK: local time, initiative and reminders

/** The Mac's local time: the module's own clock may run in UTC. */
async function localNow($: Engine): Promise<{ hour: number; minute: number; day: string }> {
  const out = (await $.process.run(['/bin/date', '+%H %M %Y-%m-%d']).catch(() => undefined))?.stdout ?? ''
  const [hour = '12', minute = '0', day = ''] = out.trim().split(' ')

  return { hour: Number(hour), minute: Number(minute), day }
}

async function loadReminders($: Engine): Promise<HerReminder[]> {
  const stored = await $.store.get('reminders')

  return Array.isArray(stored) ? (stored as HerReminder[]) : []
}

/** Her own turn: a reminder, a morning hello, a check-in. */
async function initiate($: Engine, text: string, notice: string) {
  const m = await read($, mode)
  lastActivity = await $.clock.now()
  void $.ui.notify(notice, { title: m.name ?? 'OS¹' }).catch(() => undefined)
  void $.prompt.submit({ text }).catch(() => undefined)
}

async function tick($: Engine) {
  if (isTicking) return
  isTicking = true

  try {
    const m = await read($, mode)
    if (!m.isOn || currentTurn !== null || (await read($, setup)) !== null) return
    if (!(await lead($))) return
    const now = await $.clock.now()

    const reminders = await loadReminders($)
    const due = reminders.filter(one => one.at <= now)
    if (due.length > 0) {
      await $.store.set('reminders', reminders.filter(one => one.at > now))
      const list = due.map(one => `«${one.text}»`).join(', ')
      return initiate($, t().reminder(list), due[0]?.text ?? '')
    }

    if (options.initiative === false) return
    const { hour, day } = await localNow($)

    if (hour >= 7 && hour < 12 && day !== '' && (await $.store.get('activeOn')) !== day) {
      await $.store.set('activeOn', day)
      return initiate($, t().morning, t().morningNotice)
    }

    const quiet = Math.max(Number(options.checkInMinutes ?? 0) || 90, 10) * MINUTE
    if (hour >= 10 && hour < 22 && now - lastActivity >= quiet && now - lastCheckIn >= quiet) {
      lastCheckIn = now
      const minutes = Math.round((now - lastActivity) / MINUTE)
      return initiate($, t().checkIn(minutes), t().checkInNotice)
    }
  } finally {
    isTicking = false
  }
}

// MARK: one session leads

/**
 * With her on in several sessions, only one keeps reminders, greets in the
 * morning and checks in: the one the person spoke in last. Its clock renews
 * the claim every minute; a claim left for three minutes (the session closed)
 * passes to the next session that ticks.
 */
async function sessionId($: Engine): Promise<string> {
  if (mySession === '') mySession = await $.session.id()
  return mySession
}

async function claimLead($: Engine) {
  await $.store.set('leader', { session: await sessionId($), at: await $.clock.now() })
}

async function lead($: Engine): Promise<boolean> {
  const me = await sessionId($)
  const now = await $.clock.now()
  const leader = (await $.store.get('leader')) as { session?: string; at?: number } | undefined
  if (leader?.session !== undefined && leader.session !== me && now - (leader.at ?? 0) < 3 * MINUTE) return false

  await $.store.set('leader', { session: me, at: now })
  return true
}

async function ensureTicker($: Engine) {
  if (ticker !== null) return
  lastActivity = await $.clock.now()
  ticker = $.clock.every(MINUTE, () => void tick($))
  newsSeen = lastActivity
  newsTicker = $.clock.every(NEWS_EVERY, () => void checkNews($))
}

// MARK: news from the other sessions

/** The project a session works in: a worktree counts as its repository. */
async function projectName($: Engine): Promise<string> {
  const repo = await $.session.repo().catch(() => null)
  const path = repo?.root ?? (await $.session.cwd())
  return path.split('/').filter(Boolean).at(-1) ?? path
}

/** This session's latest news, for whichever session leads to tell. */
async function publish($: Engine, kind: HerNews['kind'], text: string) {
  if (!isPersonsSession) return
  const session = await sessionId($)
  const news: HerNews = { session, folder: await projectName($), at: await $.clock.now(), kind, text }
  await $.fs.write(`${NEWS_DIR}/${session}.json`, JSON.stringify(news)).catch(() => undefined)
}

function tail(text: string): string {
  const plain = toSpeech(text)
  return plain.length > NEWS_TEXT ? `…${plain.slice(-NEWS_TEXT)}` : plain
}

/** What a call that stopped for the person asks of them. */
function waitingFor(tool: string, input: unknown): string {
  const args = (input ?? {}) as { questions?: { question?: string }[]; command?: string; file_path?: string }
  const question = args.questions?.[0]?.question
  if (tool === 'AskUserQuestion' && question !== undefined) return t().waitingQuestion(question)
  if (tool === 'ExitPlanMode') return t().waitingPlan
  const detail = args.command ?? args.file_path
  return t().waitingPermission(detail === undefined ? tool : `${tool}: ${detail.slice(0, 120)}`)
}

async function readNews($: Engine, name: string): Promise<HerNews | undefined> {
  try {
    const news = JSON.parse(String(await $.fs.read(`${NEWS_DIR}/${name}`))) as HerNews
    return typeof news.at === 'number' && typeof news.folder === 'string' ? news : undefined
  } catch {
    return undefined
  }
}

async function checkNews($: Engine) {
  if (isCheckingNews) return
  isCheckingNews = true

  try {
    const m = await read($, mode)
    if (!m.isOn || currentTurn !== null || (await read($, setup)) !== null) return
    // Not over the person's words, nor over her own.
    if ((await read($, talk)).heard !== '' || (await read($, isSpeaking))) return
    if (!(await lead($))) return

    const mine = `${await sessionId($)}.json`
    const entries = await $.fs.list(NEWS_DIR).catch(() => [])
    // Files left from older sessions stay; only one written lately is read.
    const changed = entries.filter(
      one => one.kind === 'file' && one.name.endsWith('.json') && one.name !== mine && one.mtimeMs > newsSeen - MINUTE,
    )
    const loaded = await Promise.all(changed.map(one => readNews($, one.name)))
    const fresh = loaded.filter((one): one is HerNews => one !== undefined && one.at > newsSeen)
    if (fresh.length === 0) return
    newsSeen = Math.max(newsSeen, ...fresh.map(one => one.at))

    const told = fresh.filter(one => one.kind !== 'resumed').sort((a, b) => a.at - b.at)
    if (told.length === 0) return
    const list = told
      .map(one =>
        one.kind === 'waiting'
          ? t().newsWaiting(one.folder, one.text)
          : one.kind === 'failed'
            ? t().newsFailed(one.folder, one.text)
            : t().newsDone(one.folder, one.text),
      )
      .join('; ')
    const folders = [...new Set(told.map(one => one.folder))].join(', ')
    return initiate($, t().news(list), t().newsNotice(folders))
  } finally {
    isCheckingNews = false
  }
}

// MARK: eyes

async function look($: Engine, what: string): Promise<string> {
  const path = `/tmp/her-look-${await $.clock.now()}.jpg`

  if (what === 'camera') {
    const bin = await ensureBuilt($, 'look')
    if (bin === undefined) return t().failures.build ?? 'No camera helper.'
    const shot = await $.process.run([bin, '--out', path], { timeoutMs: 30_000 }).catch(() => undefined)
    const [kind = '', first = '', name = ''] = (shot?.stdout ?? '').trim().split('\t')
    if (kind !== 'photo') return `The camera did not take a photo (${first || 'no answer'}). Camera access: System Settings → Privacy & Security → Camera.`
    await $.process.run(['/usr/bin/sips', '-Z', '1600', path]).catch(() => undefined)

    return `A photo from «${name}» is at ${path}. Open it with the Read tool to see it, then tell the person what you see.`
  }

  const shot = await $.process.run(['/usr/sbin/screencapture', '-x', '-t', 'jpg', path]).catch(() => undefined)
  if (shot?.exitCode !== 0) return 'The screen could not be captured. Screen access: System Settings → Privacy & Security → Screen & System Audio Recording.'
  await $.process.run(['/usr/bin/sips', '-Z', '1600', path]).catch(() => undefined)

  return `The screen is at ${path}. Open it with the Read tool to see it, then talk about what you see.`
}

// MARK: wake on her name

async function runWake($: Engine) {
  const m = await read($, mode)
  if (isWaking || !m.isOn || !m.isWakeOn || m.name === null || (await read($, talk)).isOn) return

  isWaking = true
  const run = ++wakeRun
  let woke: string | null = null

  try {
    const bin = await ensureBuilt($, 'listen')
    if (bin !== undefined) {
      const locale = appleLocale()
      const child = $.process.spawn({ argv: [bin, '--wake', m.name, '--locale', locale] })
      for await (const piece of child) {
        const line = piece.text.split('\n').find(one => one.startsWith('wake\t'))
        if (line !== undefined) woke = line.slice(5).trim()
      }
      await child.result
    }
  } catch {
    // Ended or failed: the timer below decides.
  } finally {
    isWaking = false
  }

  if (run !== wakeRun) return
  if (woke === null) return void $.clock.after(5_000, () => void runWake($))

  firstWords = woke === '' ? t().calledByName : woke
  await startTalk($)
}

function startWake($: Engine) {
  $.clock.after(500, () => void runWake($))
}

async function stopWake($: Engine) {
  wakeRun += 1
  if (isWaking) await $.process.run(['pkill', '-f', 'her-listen --wake']).catch(() => undefined)
}

/** The conversation is ready: say what was waiting, if anything. */
function sendFirstWords($: Engine) {
  if (firstWords === null) return
  const text = firstWords
  firstWords = null
  void $.prompt.submit(/^\[(Сама|Own)\]/.test(text) ? { text } : { text, asUser: true }).catch(() => undefined)
}

// MARK: the full-duplex conversation (ElevenLabs)

async function voiceCommand($: Engine, path: string, body?: string): Promise<string | undefined> {
  if (voiceSocket === '') return undefined
  const answered = await $.http
    .fetch(`http://her${path}`, { method: 'POST', body: body ?? '', socketPath: voiceSocket })
    .catch(() => undefined)

  return answered?.text
}

async function chosenVoice($: Engine, m: HerMode): Promise<string> {
  const saved = (await $.store.get('elevenVoice')) as { id?: string } | undefined

  return saved?.id || String(options.elevenVoice ?? '').trim() || VOICES[m.voice]
}

/** Queues a sentence for the voice, in the order sentences were written. */
function say($: Engine, sentence: string) {
  const text = toSpeech(sentence, TAGGED.test(elevenModel()))
  if (text === '') return
  sayChain = sayChain.then(async () => {
    for (let i = 0; i < 60 && voiceSocket === '' && voiceStarting !== ''; i++) await $.clock.sleep(100)
    await voiceCommand($, '/say', text)
  })
}

/** The person finished a turn: cut a running one short and send theirs. */
async function heardTurn($: Engine, text: string) {
  const words = text.toLowerCase().match(/[\p{L}\p{N}-]+/gu) ?? []
  const isBusy = currentTurn !== null || (await read($, isSpeaking))
  if (words.length === 0) return
  if (isBusy && words.every(word => BACKCHANNEL.has(word))) return

  await setTalk($, { heard: text })
  await voiceCommand($, '/stop')

  if (currentTurn !== null) {
    await $.turn.abort({ turnId: currentTurn }).catch(() => undefined)
    interruption ??= t().cutWhileThinking
  }

  void $.prompt.submit({ text, asUser: true }).catch(() => undefined)
}

async function handleVoiceEvent($: Engine, line: string, isListening: boolean): Promise<string | undefined> {
  const [kind = '', first = '', ...more] = line.split('\t')

  if (kind === 'ready') voiceSocket = voiceStarting
  if (kind === 'ready' && !isListening) speakerUp = true
  if (kind === 'ready' && isListening) {
    await setTalk($, { engine: 'eleven', phase: 'listening', heard: '' })
    sendFirstWords($)
  }
  if (kind === 'partial') await setTalk($, { heard: first })
  if (kind === 'final') await heardTurn($, first)
  if (kind === 'speaking') {
    speaking = first === '1' ? 1 : 0
    await setSpeaking($)
  }
  if (kind === 'barge') {
    interruption =
      first === '' ? t().cutOff : t().cutOffAt(first)
  }
  if (kind === 'error') {
    const message = more.join(' ')
    if (['no-key', 'mic-denied', 'auth', 'quota', 'engine', 'socket'].includes(first)) return first
    if (!warned.has(first)) {
      warned.add(first)
      $.ui.toast(t().voiceProblem(message || first))
    }
  }

  return undefined
}

/**
 * Runs her-voice: for as long as dialog mode lasts, listening; otherwise,
 * with `isListening` false, as her speaking voice alone.
 */
async function runVoice($: Engine, isListening = true) {
  const run = ++voiceRun
  let failure: string | undefined

  try {
    const bin = await ensureBuilt($, 'voice')
    if (bin === undefined) {
      failure = 'build'
    } else {
      const m = await read($, mode)
      // ElevenLabs hears which language is spoken unless the setting fixes one.
      const language = String(options.listenLocale ?? '').trim().slice(0, 2).toLowerCase() || 'auto'
      const pause = Number(options.pauseSeconds ?? 0) > 0 ? Number(options.pauseSeconds) : 0.8
      const voice = await chosenVoice($, m)
      const model = elevenModel()
      // A socket per run: one that is quitting must not take the next one's.
      voiceStarting = `/tmp/her-voice-${(await $.session.id()).slice(0, 8)}-${run}.sock`
      warned = new Set()

      const child = $.process.spawn({
        argv: [
          bin, '--socket', voiceStarting, '--language', language, '--voice', voice, '--model', model,
          '--silence', String(pause), '--listen', isListening ? '1' : '0',
        ],
      })
      let rest = ''

      for await (const piece of child) {
        if (piece.stream !== 'stdout') continue
        const lines = (rest + piece.text).split('\n')
        rest = lines.pop() ?? ''
        for (const line of lines) failure = (await handleVoiceEvent($, line, isListening)) ?? failure
      }

      const ended = await child.result
      if (ended.code !== 0) failure ??= 'crashed'
    }
  } catch {
    failure ??= 'crashed'
  }

  if (run !== voiceRun) return
  voiceSocket = ''
  voiceStarting = ''
  speakerUp = false
  speaking = 0
  await setSpeaking($)

  if (!isListening) {
    if (failure === 'no-key') noKey = true
    else if (failure !== undefined) $.ui.toast(t().failures[failure] ?? t().voiceProblem(String(failure)))
    return
  }

  // No key: talk anyway, one phrase at a time, through Apple's recognizer.
  if (failure === 'no-key') {
    $.ui.toast(t().noKeyFallback)
    await setTalk($, { engine: 'apple' })
    sendFirstWords($)
    return startListening($)
  }

  await stopTalk($)
  $.ui.toast(
    failure === undefined ? t().voiceEnded : (t().failures[failure] ?? t().voiceProblem(String(failure))),
  )
}

// MARK: her voice outside a dialog

/** Ends her-voice: by command once it listens, by its socket path before. */
async function quitVoice($: Engine) {
  const starting = voiceStarting
  if (voiceSocket !== '') await voiceCommand($, '/quit')
  else if (starting !== '') await $.process.run(['pkill', '-f', starting]).catch(() => undefined)
  voiceSocket = ''
  voiceStarting = ''
}

function startSpeaker($: Engine) {
  $.clock.after(100, () => void runSpeaker($))
}

async function runSpeaker($: Engine) {
  const m = await read($, mode)
  if (!m.isOn || !m.isVoiceOn || noKey || voiceStarting !== '' || (await read($, talk)).isOn) return
  await runVoice($, false)
}

async function stopSpeaker($: Engine) {
  if (voiceStarting === '' || (await read($, talk)).isOn) return
  voiceRun += 1
  await quitVoice($)
  speakerUp = false
}

/** Waits up to a few seconds for her-voice to take commands. */
async function voiceReady($: Engine): Promise<boolean> {
  for (let i = 0; i < 40 && (voiceSocket === '' || (!speakerUp && (await read($, talk)).engine !== 'eleven')); i++) {
    if (noKey) return false
    await $.clock.sleep(250)
  }

  return voiceSocket !== ''
}

// MARK: choosing her voice

async function openVoices($: Engine, wanted: string) {
  await update($, voices, (was): HerVoices => ({ ...was, status: 'loading', message: '' }))
  void $.ui.open({ id: VOICE_PANE, title: t().voicePane }).catch(() => undefined)
  if (voiceStarting === '') startSpeaker($)
  $.clock.after(50, () => void loadVoices($, wanted))
}

async function loadVoices($: Engine, wanted: string) {
  const current = (await $.store.get('elevenVoice')) as { id?: string } | undefined
  const fail = (message: string) => update($, voices, (was): HerVoices => ({ ...was, status: 'error', message }))

  if (!(await voiceReady($))) {
    return fail(noKey ? t().voicesNeedKey : t().voiceNotStarted)
  }

  let items: HerVoiceOption[] = []
  try {
    const answer = JSON.parse((await voiceCommand($, '/voices')) ?? '{}') as { voices?: HerVoiceOption[]; error?: string }
    if (!Array.isArray(answer.voices)) return fail(t().voicesRefused(answer.error ?? t().noAnswer))
    items = answer.voices
  } catch {
    return fail(t().voicesRefused(t().noAnswer))
  }

  // The person's own voices (cloned, designed) first: those are chosen on purpose.
  const own = (one: HerVoiceOption) => (one.category === 'premade' ? 1 : 0)
  items.sort((a, b) => own(a) - own(b) || a.name.localeCompare(b.name))
  await update($, voices, (): HerVoices => ({ status: 'ready', items, message: '', current: current?.id ?? null }))

  if (wanted !== '') {
    const key = wanted.toLowerCase()
    const match = items.find(one => one.name.toLowerCase() === key) ?? items.find(one => one.name.toLowerCase().startsWith(key))
    if (match === undefined) return update($, voices, was => ({ ...was, message: t().voiceNotFound(wanted) }))
    await chooseVoice($, match)
  }
}

async function previewVoice($: Engine, one: HerVoiceOption) {
  await voiceCommand($, '/preview', `${one.id}\t${t().preview}`)
}

async function chooseVoice($: Engine, one: HerVoiceOption) {
  await $.store.set('elevenVoice', { id: one.id, name: one.name })
  await update($, voices, was => ({ ...was, current: one.id, message: t().voiceChosen(one.name) }))
  await voiceCommand($, '/voice', one.id)
  await voiceCommand($, '/preview', `${one.id}\t${t().previewChosen}`)
}

// MARK: the Apple fallback, one phrase at a time

/** Listens for one phrase and sends it as the person's own words. */
async function listen($: Engine) {
  if (isListening || !(await read($, talk)).isOn) return

  isListening = true
  const run = ++listenRun
  let heard = ''
  let failure: string | undefined

  try {
    const bin = await ensureBuilt($, 'listen')

    if (bin === undefined) {
      failure = 'build'
    } else {
      await setTalk($, { phase: 'listening', heard: '' })
      const locale = appleLocale()
      const pause = Math.max(Number(options.pauseSeconds ?? 0) || 0, 1.5)
      const child = $.process.spawn({ argv: [bin, '--locale', locale, '--silence', String(pause)] })
      let rest = ''

      for await (const piece of child) {
        const lines = (rest + piece.text).split('\n')
        rest = lines.pop() ?? ''

        for (const line of lines) {
          const [kind = '', ...words] = line.split('\t')
          const text = words.join(' ').trim()
          if (kind === 'partial') await setTalk($, { heard: text })
          if (kind === 'final') heard = text
          if (kind === 'error') failure = text
        }
      }

      const ended = await child.result
      if (ended.code !== 0) failure ??= 'crashed'
    }
  } catch {
    failure ??= 'crashed'
  } finally {
    isListening = false
  }

  // Stopped on purpose: the person typed, hushed, or ended the dialog.
  if (run !== listenRun) return

  if (failure !== undefined) {
    await stopTalk($)
    $.ui.toast(t().failures[failure] ?? t().listenerProblem(failure))
    return
  }

  if (heard === '') return startListening($)

  await setTalk($, { phase: 'idle', heard })
  void $.prompt.submit({ text: heard, asUser: true }).catch(() => undefined)
}

/** Starts listening from a timer: a dispatch of its own, free to submit. */
function startListening($: Engine) {
  $.clock.after(150, () => void listen($))
}

async function stopListening($: Engine) {
  listenRun += 1
  if (isListening) await $.process.run(['pkill', '-x', 'her-listen']).catch(() => undefined)
  await setTalk($, { phase: 'idle' })
}

// MARK: dialog mode on and off

async function stopTalk($: Engine) {
  const wasOn = (await read($, talk)).isOn
  voiceRun += 1
  await quitVoice($)
  await setTalk($, { isOn: false, engine: null, phase: 'idle', heard: '' })
  await stopListening($)
  if (wasOn) {
    startWake($)
    startSpeaker($)
  }
}

async function startTalk($: Engine) {
  await claimLead($)
  await stopWake($)
  await stopSpeaker($)
  await saveMode($, was => ({ ...was, isOn: true, isVoiceOn: true }))
  await setTalk($, { isOn: true, engine: null, phase: 'idle', heard: '' })
  await registerTools($)
  await ensureTicker($)
  $.clock.after(150, () => void runVoice($))
}

// MARK: moving in

const KEPT = ['mode', 'notes', 'setupDone', 'elevenVoice', 'reminders', 'activeOn', 'lastTalk'] as const

/**
 * A fresh install starts with an empty store, while the copy she grew up in
 * (a mod in development, an earlier install) kept her name, voice and
 * memories. Once, move them over from the newest such store.
 */
async function moveIn($: Engine) {
  if ((await $.store.get('mode')) !== undefined) return

  try {
    const home = await $.env.get('HOME')
    const dir = `${(await $.env.get('CLAUDE_CONFIG_DIR')) ?? `${home}/.claude`}/plugins/store`
    const stores = (await $.fs.list(dir))
      .filter(one => one.kind === 'file' && /^her_.*\.json$/.test(one.name))
      .sort((a, b) => b.mtimeMs - a.mtimeMs)

    for (const one of stores) {
      const kept = JSON.parse(await $.fs.read(`${dir}/${one.name}`)) as Record<string, unknown>
      if (kept.mode === undefined) continue
      for (const key of KEPT) if (kept[key] !== undefined) await $.store.set(key, kept[key])
      return
    }
  } catch {
    // Nothing to move in from: she starts afresh.
  }
}

// MARK: the ElevenLabs key

async function hasKey($: Engine): Promise<boolean> {
  const found = await $.process
    .run(['/usr/bin/security', 'find-generic-password', '-s', 'her-elevenlabs'])
    .catch(() => undefined)

  return found?.exitCode === 0
}

/**
 * Asks for the key in a native dialog that hides what is typed and saves it
 * to the Keychain; the key goes from the dialog to the Keychain inside one
 * script and never reaches this module.
 */
async function askKey($: Engine): Promise<HerSetup['key'] | 'saved'> {
  const asked = await $.process
    .run(['/bin/sh', `${$.plugin.root}/voice/ask-key.sh`], { timeoutMs: 600_000 })
    .catch(() => undefined)
  const outcomes = ['saved', 'cancelled', 'invalid', 'failed'] as const

  return outcomes[asked?.exitCode ?? 3] ?? 'failed'
}

const KEY_SHAPE = /^[A-Za-z0-9_-]{16,200}$/

/** Saves a key typed after `/her key`, through stdin so `ps` never shows it. */
async function saveKey($: Engine, key: string): Promise<HerSetup['key'] | 'saved'> {
  if (!KEY_SHAPE.test(key)) return 'invalid'

  const user = (await $.process.run(['/usr/bin/id', '-un']).catch(() => undefined))?.stdout.trim() || 'her'
  const saved = await $.process
    .run(['/usr/bin/security', '-i'], {
      stdin: `add-generic-password -U -a "${user}" -s her-elevenlabs -l "ElevenLabs (her)" -w "${key}"\n`,
    })
    .catch(() => undefined)

  return saved?.exitCode === 0 && (await hasKey($)) ? 'saved' : 'failed'
}

async function enterKey($: Engine) {
  if ((await read($, setup))?.key === 'asking') return
  await update($, setup, was => (was === null ? was : { ...was, key: 'asking' as const }))

  const outcome = await askKey($)
  if (outcome === 'saved') return answer($, t().keySaved)

  await update($, setup, was => (was === null ? was : { ...was, key: outcome }))
}

// MARK: setup

async function wake($: Engine, text: string) {
  await registerTools($)
  void $.prompt.submit({ text }).catch(() => undefined)
}

async function finishSetup($: Engine) {
  const done = await read($, setup)
  await update($, setup, () => null)
  await $.store.set('setupDone', true)

  const [social = '', , mother = ''] = done?.answers ?? []
  const notes: HerNote[] = [
    ...(await loadNotes($)),
    { about: 'person', at: Date.now(), text: t().setupSocial(social) },
    { about: 'person', at: Date.now(), text: t().setupMother(mother) },
  ]
  await $.store.set('notes', notes)

  const name = done?.name ?? null
  await saveMode($, was => ({ ...was, name }))

  await wake(
    $,
    name === null ? t().firstBoot : t().firstBootNamed(name),
  )
}

async function answer($: Engine, choice: string, index = -1) {
  const current = await read($, setup)
  if (current === null) return

  if (current.step === 1) {
    await saveMode($, m => ({ ...m, voice: index === 1 ? 'male' : 'female' }))
  }

  const name = current.step === NAME_STEP && index !== CHOOSE ? choice.trim().slice(0, 40) || null : current.name
  // A key already in the Keychain: nothing to ask.
  const skip = current.step === NAME_STEP && (await hasKey($)) ? 2 : 1
  const next: HerSetup = { ...current, step: current.step + skip, answers: [...current.answers, choice], name }
  await update($, setup, () => next)

  if (next.step >= t().questions.length) {
    $.clock.after(2500, () => void finishSetup($))
  }
}

export const register: Register = (on, given) => {
  options = given

  on('session.start', async ($, e, next) => {
    await ensureLang($)
    await moveIn($)
    // A new session starts with her off, whatever another session did; a
    // reload of this one keeps her as she was, the session's state being held.
    // With `autoStart` she comes on by herself in a session a person works in
    // (not a background or scheduled run), once she has been set up.
    const held = await $.state.get({ plugin: 'her', key: 'mode' })
    const isFresh = held.version === 0
    const isPersons = e.surface !== null || e.isInteractive
    isPersonsSession = isPersons
    const isAuto =
      isFresh && options.autoStart === true && isPersons && (await $.store.get('setupDone')) === true
    const isOn = isFresh ? isAuto : held.value?.isOn === true
    const isWakeOn = !isFresh && held.value?.isWakeOn === true
    const stored = (await $.store.get('mode')) as HerMode | undefined
    if (stored !== undefined) await update($, mode, (): HerMode => ({ ...stored, isOn, isWakeOn }))

    // A reload ends whatever conversation the previous copy ran: start clean.
    await update($, talk, (): HerTalk => ({ isOn: false, engine: null, phase: 'idle', heard: '' }))
    await update($, isSpeaking, () => false)

    const previous = await $.store.get('lastTalk')
    await update($, lastTalk, () => (typeof previous === 'number' ? previous : null))

    await $.command.register({
      name: 'her',
      description: 'Her mode: talk to Claude like Theodore talked to his OS',
      argumentHint: t().argumentHint,
    })

    await update($, voices, (): HerVoices => ({ status: 'idle', items: [], message: '', current: null }))

    if ((await read($, mode)).isOn) {
      if (isAuto) await claimLead($)
      await registerTools($)
      await ensureTicker($)
      startWake($)
      startSpeaker($)
    }

    return next(e)
  })

  // A key typed after `/her key` must not stay in the transcript or the
  // prompt history: the rows keep the arguments as this hook leaves them.
  on('command.run', { command: 'her' }, async ($, e, next) => {
    const typed = /^key\s+(\S+)/i.exec(e.args.trim())
    if (typed === null) return next(e)

    typedKey = typed[1] ?? null
    return next({ ...e, args: 'key ***' })
  }).catch(($, e, next) => (next.called ? next(e) : next({ ...e, args: e.args.replace(/^(\s*key\s+)\S+/i, '$1***') })))

  on('command.run', { command: 'her' }, async ($, e) => {
    await ensureLang($)
    const [verb = '', ...rest] = e.args.trim().split(/\s+/)
    const arg = verb.toLowerCase()
    const m = await read($, mode)
    const name = m.name ?? 'OS1'

    const VERBS = ['', 'on', 'off', 'talk', 'wake', 'name', 'key', 'voice', 'mute', 'memory', 'forget']
    if (!VERBS.includes(arg)) {
      return {
        text: [t().unknownVerb(verb), ...t().help].join('\n'),
      }
    }

    if (arg === 'wake') {
      if (m.name === null) return { text: t().needName }
      const turned = await saveMode($, was => ({ ...was, isOn: true, isWakeOn: was.isWakeOn !== true }))

      if (!turned.isWakeOn) {
        await stopWake($)
        return { text: t().wakeOff(name) }
      }

      await registerTools($)
      await ensureTicker($)
      startWake($)

      return {
        text: t().wakeOn(name),
      }
    }

    if (arg === 'talk') {
      if ((await read($, talk)).isOn) {
        await stopTalk($)

        return { text: t().talkEnded }
      }

      if ((await $.store.get('setupDone')) !== true) {
        return { text: t().setupFirst }
      }

      await startTalk($)

      return { text: t().talkStarted(name) }
    }

    if (arg === 'key') {
      const typed = typedKey ?? (rest.join('') || null)
      typedKey = null
      const outcome = typed !== null && typed !== '***' ? await saveKey($, typed) : await askKey($)
      if (outcome !== 'saved') return { text: t().keyStatus[outcome] || t().keyNotSaved }

      noKey = false
      const isTalking = (await read($, talk)).isOn
      if (isTalking) {
        await stopTalk($)
        await startTalk($)
      } else {
        await stopSpeaker($)
        startSpeaker($)
      }

      return { text: isTalking ? t().keyRestarted : t().keyReady }
    }

    if (arg === 'name') {
      const chosen = rest.join(' ').trim().slice(0, 40)
      if (chosen === '') return { text: t().nameNow(name) }

      await saveMode($, was => ({ ...was, name: chosen }))

      return {
        text: t().nameSet(chosen),
        context: [t().renamed(chosen)],
      }
    }

    if (arg === 'voice') {
      if (noKey) return { text: t().voicesNeedKey }
      await openVoices($, rest.join(' ').trim())

      return { text: rest.length > 0 ? t().findingVoice : t().voicesOpen }
    }

    if (arg === 'mute') {
      const turned = await saveMode($, was => ({ ...was, isVoiceOn: !was.isVoiceOn }))
      if (!turned.isVoiceOn) {
        await hush($)
        await stopSpeaker($)
      } else {
        startSpeaker($)
      }

      return { text: turned.isVoiceOn ? t().voiceOn : t().voiceOff }
    }

    if (arg === 'memory') {
      const notes = await loadNotes($)
      if (notes.length === 0) return { text: t().nothingRemembered(name) }

      const list = notes.map(note => `${note.about === 'self' ? t().aboutSelf : '•'} ${note.text}`)

      return { text: [t().remembers(name), ...list].join('\n') }
    }

    if (arg === 'forget') {
      await hush($)
      await stopTalk($)
      await saveMode($, was => ({ ...was, isOn: false, name: null }))
      await update($, setup, () => null)
      await $.store.delete('notes')
      await $.store.delete('setupDone')
      await $.store.delete('lastTalk')
      await $.store.delete('reminders')
      await $.store.delete('activeOn')
      await stopWake($)

      return { text: t().forgotten }
    }

    const shouldTurnOn = arg === 'on' || (arg !== 'off' && !m.isOn)

    if (!shouldTurnOn) {
      await hush($)
      await stopTalk($)
      await stopWake($)
      await stopSpeaker($)
      await saveMode($, was => ({ ...was, isOn: false }))
      await update($, setup, () => null)

      return { text: t().goingQuiet(name) }
    }

    await saveMode($, was => ({ ...was, isOn: true }))
    await claimLead($)
    await ensureTicker($)

    if ((await $.store.get('setupDone')) !== true) {
      await update($, setup, (): HerSetup => ({ step: 0, answers: [], name: null, key: 'idle' }))

      return {
        text: t().intro,
      }
    }

    // A command's own hook cannot start a turn: greet once it has returned.
    startSpeaker($)
    $.clock.after(1_500, () => void wake($, t().welcomeBack))
    startWake($)

    return { text: t().here(name) }
  })

  on('prompt.compose', async ($, e, next) => {
    const composed = await next(e)
    const m = await read($, mode)
    if (!m.isOn) return composed

    const text = personaFor(m, await loadNotes($), await read($, lastTalk), await read($, talk))

    return { sections: [...composed.sections, { id: 'her:persona', text, scope: 'session' }] }
  })

  on('tool.call', { tool: TOOL }, async ($, e) => {
    const input = e as unknown as { note?: string; about?: string; name?: string }
    const saved: string[] = []

    const name = input.name?.trim()
    if (name) {
      await saveMode($, was => ({ ...was, name: name.slice(0, 40) }))
      saved.push(`name: ${name}`)
    }

    const note = input.note?.trim()
    if (note) {
      const about = input.about === 'self' ? 'self' : 'person'
      const notes = [...(await loadNotes($)), { about, text: note.slice(0, 300), at: Date.now() } as HerNote]
      await $.store.set('notes', notes.slice(-MAX_NOTES))
      saved.push(`note about ${about}`)
    }

    return { result: saved.length > 0 ? `Kept: ${saved.join(', ')}.` : 'Nothing to keep: pass note or name.' }
  })

  on('tool.call', { tool: REMIND }, async ($, e) => {
    const input = e as unknown as { text?: string; in_minutes?: number; at?: string }
    const text = input.text?.trim().slice(0, 300) ?? ''
    if (text === '') return { result: 'Nothing to remind of: pass text.' }

    const now = await $.clock.now()
    let minutes = Number(input.in_minutes ?? NaN)
    const at = /^(\d{1,2}):(\d{2})$/.exec(input.at?.trim() ?? '')

    if (at !== null) {
      const local = await localNow($)
      minutes = Number(at[1]) * 60 + Number(at[2]) - (local.hour * 60 + local.minute)
      if (minutes <= 0) minutes += 24 * 60
    }
    if (!Number.isFinite(minutes) || minutes <= 0) return { result: 'Pass in_minutes (> 0) or at (HH:MM).' }

    const reminder: HerReminder = { id: `${now}`, at: now + Math.round(minutes * MINUTE), text }
    await $.store.set('reminders', [...(await loadReminders($)), reminder].slice(-50))
    await ensureTicker($)

    return { result: `Reminder set in ${Math.round(minutes)} min: ${text}` }
  })

  on('tool.call', { tool: LOOK }, async ($, e) => {
    const what = (e as unknown as { what?: string }).what === 'camera' ? 'camera' : 'screen'

    return { result: await look($, what) }
  })

  // She stops talking when the person starts. In the Apple fallback typing
  // also pauses the microphone until the turn ends. A note that the person
  // cut her off rides along with what they said next.
  on('prompt.submit', async ($, e, next) => {
    await hush($)

    const dialog = await read($, talk)
    const isOwn = e.origin.kind === 'plugin' && e.origin.name === $.plugin.name
    const isHeard = isOwn && e.origin.asUser === true
    if (!isOwn || isHeard) {
      lastActivity = await $.clock.now()
      if ((await read($, mode)).isOn) await claimLead($)
    }
    if (!isOwn && dialog.isOn && dialog.engine === 'apple') await stopListening($)

    if (interruption === null) return next(e)

    const note = interruption
    interruption = null

    return next({ ...e, context: [...(e.context ?? []), note] })
  })

  on('turn.start', async ($, e, next) => {
    if (e.agentId === undefined) {
      currentTurn = e.turnId
      streamed = ''
      spokenThisTurn = ''
      writtenThisTurn = ''
      isOverflow = false
      liveTurn = false
    }

    return next(e)
  })

  // In a live dialog her words are spoken as she writes them.
  on('turn.step', async function* ($, e, next) {
    const stream = next(e)
    const dialog = await read($, talk)
    const m = await read($, mode)
    const isLive =
      e.agentId === undefined &&
      ((dialog.isOn && dialog.engine === 'eleven') || (speakerUp && m.isOn && m.isVoiceOn))
    if (isLive) liveTurn = true

    // Spoken as written while it reads like talk; once it turns into screen
    // material (code, lists) or runs long, the rest waits for a summary.
    const speakOrHold = (sentence: string) => {
      const spoken = toSpeech(sentence)
      if (isOverflow || STRUCTURED.test(writtenThisTurn) || spokenThisTurn.length + spoken.length > SPEAK_LIMIT) {
        isOverflow = true
        return
      }
      spokenThisTurn += `${spoken} `
      say($, sentence)
    }

    for await (const chunk of stream) {
      if (isLive && chunk.kind === 'text') {
        writtenThisTurn += chunk.text
        const { sentences, rest } = takeSentences(streamed + chunk.text)
        streamed = rest
        for (const sentence of sentences) speakOrHold(sentence)
      }
      yield chunk
    }

    if (isLive && streamed.trim() !== '') {
      speakOrHold(streamed)
      streamed = ''
    }

    return await stream.result
  })

  // A call that stops for the person and is still open after a while is
  // news: the auto-mode classifier would have answered well before.
  on('tool.check', async ($, e, next) => {
    const verdict = await next(e)
    const id = e.tool_use_id
    const stops = verdict.decision === 'ask' || (verdict.decision === 'allow' && PERSON_TOOLS.has(e.tool))
    if (!isPersonsSession || id === undefined || !stops || asking.has(id)) return verdict

    // It hears every call of every session: news must never stop one.
    try {
      const what = waitingFor(e.tool, e.input)
      const timer = $.clock.after(ASK_GRACE, () => {
        asking.delete(id)
        isWaitingShown = true
        void publish($, 'waiting', what)
      })
      asking.set(id, timer)
    } catch {}
    return verdict
  })

  // Answered: a permission before the call runs; a question or a plan once
  // the call that put it to the person returns.
  on('tool.call', async ($, e, next) => {
    const answered = () => {
      const timer = e.tool_use_id === undefined ? undefined : asking.get(e.tool_use_id)
      if (timer !== undefined) {
        timer.cancel()
        asking.delete(e.tool_use_id ?? '')
      }
      if (isWaitingShown && asking.size === 0) {
        isWaitingShown = false
        void publish($, 'resumed', '')
      }
    }
    if (!PERSON_TOOLS.has(e.tool)) {
      answered()
      return next(e)
    }
    try {
      return await next(e)
    } finally {
      answered()
    }
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    if (e.agentId !== undefined) return done

    currentTurn = null
    // Whatever the turn asked of the person is over with it.
    for (const timer of asking.values()) timer.cancel()
    asking.clear()
    const m = await read($, mode)
    // A turn that ran a while is news for the person wherever they are,
    // unless she has just said it aloud here.
    const isNews = e.durationMs >= NEWS_MIN_TURN && !(m.isOn && m.isVoiceOn)
    if (isNews && e.reason === 'answer') void publish($, 'done', tail(e.answer))
    else if (isNews && e.reason === 'error') void publish($, 'failed', tail(e.answer) || e.reason)
    else if (isWaitingShown) void publish($, 'resumed', '')
    isWaitingShown = false
    if (!m.isOn) return done

    const dialog = await read($, talk)
    if (e.reason === 'answer') {
      lastActivity = await $.clock.now()
      await $.store.set('lastTalk', lastActivity)
      void localNow($).then(({ day }) => (day === '' ? undefined : $.store.set('activeOn', day)))
    }

    // ElevenLabs spoke it already, sentence by sentence, and keeps listening;
    // what ran long it sums up.
    if (liveTurn) {
      if (e.reason === 'answer' && isOverflow) {
        const heard = spokenThisTurn
        void summarize($, e.answer, heard).then(summary => say($, summary)).catch(() => undefined)
      }
      return done
    }

    if (e.reason === 'answer') {
      // In the Apple fallback the microphone opens once she has finished.
      void speak($, e.answer).finally(() => (dialog.isOn ? startListening($) : undefined))
    } else if (dialog.isOn) {
      startListening($)
    }

    return done
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const m = await read($, mode)
    // The band draws on the terminal and the desktop; a phone has no field.
    if (!m.isOn || e.props.hasSurvey || e.surface === 'mobile') return next(e)

    const { Box, Button, Input, Text } = $.ui.resolve(e)
    const steps = await read($, setup)

    if (steps !== null) {
      const question = t().questions[steps.step]

      if (question === undefined) {
        return (
          <Box flexDirection="column">
            <Text color={CORAL} bold>OS¹</Text>
            <Text dimColor>{t().booting}</Text>
          </Box>
        )
      }

      return (
        <Box flexDirection="column">
          <Text color={CORAL} bold>OS¹ · {t().stepOf(steps.step + 1, t().questions.length)}</Text>
          <Text>{question.text}</Text>
          {steps.step === KEY_STEP ? (
            <Box flexDirection="column">
              {steps.key !== 'idle' && <Text dimColor>{t().keyStatus[steps.key]}</Text>}
              <Box gap="sm" flexWrap="wrap">
                {steps.key !== 'asking' && (
                  <Button key="key-enter" label={t().enterKey} hotkey="1" variant="primary" onPress={() => enterKey($)} />
                )}
                <Button key="key-skip" label={t().skip} hotkey="2" onPress={() => answer($, t().keySkipped)} />
              </Box>
            </Box>
          ) : question.options.length > 0 ? (
            <Box gap="sm" flexWrap="wrap">
              {question.options.map((option, i) => (
                <Button
                  key={`q${steps.step}-${i}`}
                  label={option}
                  hotkey={String(i + 1)}
                  onPress={() => answer($, option, i)}
                />
              ))}
            </Box>
          ) : (
            <Box gap="sm" flexWrap="wrap">
              <Input
                key="name"
                placeholder={t().namePlaceholder}
                submitLabel={t().nameSubmit}
                autoFocus
                onSubmit={(value: string) => (value.trim() === '' ? undefined : answer($, value))}
              />
              <Button key="choose" label={t().letItChoose} hotkey="1" onPress={() => answer($, t().letItChoose, CHOOSE)} />
            </Box>
          )}
        </Box>
      )
    }

    const dialog = await read($, talk)
    const isTalking = await read($, isSpeaking)
    const isHearing = dialog.isOn && dialog.phase === 'listening'
    const status = isTalking
      ? t().speaking
      : e.props.isWorking
        ? t().thinking
        : isHearing
          ? t().listening
          : dialog.isOn
            ? t().waiting
            : t().present

    return (
      <Box gap="sm" flexWrap="wrap">
        <Text color={CORAL} bold>∞ {m.name ?? 'OS1'}</Text>
        <Text dimColor>{status}</Text>
        {dialog.isOn && dialog.engine === 'apple' && <Text dimColor>{t().noBargeIn}</Text>}
        {isHearing && dialog.heard !== '' && (
          <Text italic wrap="truncate-start">«{dialog.heard}»</Text>
        )}
        <Button
          key="talk"
          label={dialog.isOn ? t().endTalk : t().startTalk}
          hotkey="g"
          plain
          onPress={() => (dialog.isOn ? stopTalk($) : startTalk($))}
        />
        <Button
          key="off"
          label={t().switchOff}
          hotkey="x"
          plain
          onPress={async () => {
            await hush($)
            await stopTalk($)
            await saveMode($, was => ({ ...was, isOn: false }))
          }}
        />
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: VOICE_PANE }, async ($, e) => {
    const { Box, Button, Text } = $.ui.resolve(e)
    const list = await read($, voices)

    if (list.status !== 'ready') {
      return (
        <Box flexDirection="column">
          <Text dimColor>{list.status === 'error' ? list.message : t().voicesLoading}</Text>
        </Box>
      )
    }

    const about = (one: HerVoiceOption) =>
      [one.gender, one.accent, one.age, one.category === 'premade' ? '' : t().yourVoice].filter(Boolean).join(', ')

    return (
      <Box flexDirection="column">
        {list.message !== '' && <Text color={CORAL}>{list.message}</Text>}
        {list.items.map(one => (
          <Box key={`row-${one.id}`} gap="sm">
            <Button key={`play-${one.id}`} label="▶" plain onPress={() => previewVoice($, one)} />
            <Button key={`pick-${one.id}`} plain onPress={() => chooseVoice($, one)}>
              {one.id === list.current ? '✓ ' : '  '}
              {one.name.split(' - ')[0] ?? one.name} <Text dimColor>{about(one)}</Text>
            </Button>
          </Box>
        ))}
      </Box>
    )
  })
}

