files.types/index.d.ts:
export type HerVoice = 'female' | 'male'

export type HerMode = {
  isOn: boolean
  isVoiceOn: boolean
  /** The name the OS chose for itself; null until it has. */
  name: string | null
  voice: HerVoice
  /** Listening for the OS's name to start a conversation (/her wake). */
  isWakeOn?: boolean
}

/** One ElevenLabs voice of the person's account, as the voice picker lists it. */
export type HerVoiceOption = {
  id: string
  name: string
  gender?: string
  accent?: string
  age?: string
  category?: string
}

/** The voice picker: the account's voices and which one she speaks with. */
export type HerVoices = {
  status: 'idle' | 'loading' | 'ready' | 'error'
  items: HerVoiceOption[]
  message: string
  current: string | null
}

/** Something the OS promised to remind the person of, at `at` (ms). */
export type HerReminder = { id: string; at: number; text: string }

/**
 * What another session last did, as it wrote it for the OS to tell: `done`
 * with the end of its answer, `failed` with what went wrong, `waiting` with
 * what it asks of the person, or `resumed` once that was answered there.
 * `folder` names the project; `at` is when (ms).
 */
export type HerNews = {
  session: string
  folder: string
  at: number
  kind: 'done' | 'failed' | 'waiting' | 'resumed'
  text: string
}

export type HerNote = {
  about: 'person' | 'self'
  text: string
  at: number
}

/**
 * Dialog mode: a live voice conversation. `engine` is what runs it:
 * `eleven`, full duplex with barge-in (ElevenLabs and Apple's echo
 * canceller), or `apple`, one phrase at a time. `phase` is `listening` once
 * the microphone is open; `heard` the person's words so far.
 */
export type HerTalk = {
  isOn: boolean
  engine: 'eleven' | 'apple' | null
  phase: 'idle' | 'listening'
  heard: string
}

/**
 * The OS1 setup: `step` is the next question, past the last it boots;
 * `name` what the person chose to call the OS, null to let it choose;
 * `key` where asking for the ElevenLabs key stands.
 */
export type HerSetup = {
  step: number
  answers: string[]
  name: string | null
  key: 'idle' | 'asking' | 'cancelled' | 'invalid' | 'failed'
}

declare module 'claude-code' {
  interface PluginState {
    her: {
      mode: HerMode
      setup: HerSetup | null
      isSpeaking: boolean
      talk: HerTalk
      voices: HerVoices
      /** When the previous conversation ended, read once at session start. */
      lastTalk: number | null
    }
  }
}
